SELECT *, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC, id) row_seq, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at, id) seq_no, LAST_VALUE(country, TRUE) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_country, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) seq_no_2, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_country_2 FROM sessions WHERE device = 'desktop'
